// Command typegen generates the Free5GC type registry and the NAS 5GSM
// structural metadata used by protocol/codec. It reads the pinned upstream
// module sources from the Go module cache; the generated files are committed so
// normal builds never need the module source tree.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

type typeInfo struct {
	Qualified string
	Package   string
	Name      string
}

type nasField struct {
	Name    string
	Type    string
	Framing string
	IEI     uint8
	Size    int
	Partial bool
}

type nasMessage struct {
	Code       uint8
	StructName string
	TypeName   string
	Mandatory  []nasField
	Optional   []nasField
}

func main() {
	outDir := flag.String("out", "protocol/codec", "output directory")
	flag.Parse()

	ngapDir, err := moduleDir("github.com/free5gc/ngap")
	if err != nil {
		fatal(err)
	}
	nasDir, err := moduleDir("github.com/free5gc/nas")
	if err != nil {
		fatal(err)
	}

	types := []typeInfo{}
	for _, pkg := range []struct {
		prefix string
		dir    string
	}{
		{"ngap.ie", filepath.Join(ngapDir, "ie")},
		{"ngap.message", filepath.Join(ngapDir, "message")},
		{"nas.ie", filepath.Join(nasDir, "ie")},
		{"nas.message", filepath.Join(nasDir, "message")},
	} {
		found, err := collectStructs(pkg.prefix, pkg.dir)
		if err != nil {
			fatal(err)
		}
		types = append(types, found...)
	}
	sort.Slice(types, func(i, j int) bool { return types[i].Qualified < types[j].Qualified })

	if err := writeRegistry(filepath.Join(*outDir, "zz_types_generated.go"), types); err != nil {
		fatal(err)
	}

	messages, err := collectNASMessages(filepath.Join(nasDir, "message"), filepath.Join(nasDir, "ie"))
	if err != nil {
		fatal(err)
	}
	if err := writeNASMeta(filepath.Join(*outDir, "zz_nas_meta_generated.go"), messages); err != nil {
		fatal(err)
	}

	roots, err := collectN2Roots(filepath.Join(ngapDir, "ie"))
	if err != nil {
		fatal(err)
	}
	if err := writeN2Meta(filepath.Join(*outDir, "zz_n2_meta_generated.go"), roots); err != nil {
		fatal(err)
	}
	ngapMessages, err := collectNGAPMessages(filepath.Join(ngapDir, "message"))
	if err != nil {
		fatal(err)
	}
	if err := writeNGAPMeta(filepath.Join(*outDir, "zz_ngap_meta_generated.go"), ngapMessages); err != nil {
		fatal(err)
	}
	fmt.Printf("generated %d types, %d NAS 5GSM message layouts, %d N2 transfer roots and %d NGAP PDU messages\n", len(types), len(messages), len(roots), len(ngapMessages))
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "typegen:", err)
	os.Exit(1)
}

func moduleDir(path string) (string, error) {
	cmd := exec.Command("go", "list", "-m", "-f", "{{.Dir}}", path)
	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("go list -m %s: %w", path, err)
	}
	dir := strings.TrimSpace(string(out))
	if dir == "" {
		return "", fmt.Errorf("module %s has no source directory", path)
	}
	return dir, nil
}

func parsePackage(dir string) (map[string]*ast.File, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	fset := token.NewFileSet()
	files := map[string]*ast.File{}
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fset, filepath.Join(dir, name), nil, parser.ParseComments)
		if err != nil {
			return nil, err
		}
		files[name] = file
	}
	return files, nil
}

func collectStructs(prefix, dir string) ([]typeInfo, error) {
	files, err := parsePackage(dir)
	if err != nil {
		return nil, err
	}
	found := []typeInfo{}
	for _, file := range files {
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.TYPE {
				continue
			}
			for _, spec := range gen.Specs {
				ts := spec.(*ast.TypeSpec)
				if !ts.Name.IsExported() {
					continue
				}
				if _, ok := ts.Type.(*ast.StructType); !ok {
					continue
				}
				found = append(found, typeInfo{
					Qualified: prefix + "." + ts.Name.Name,
					Package:   prefix,
					Name:      ts.Name.Name,
				})
			}
		}
	}
	return found, nil
}

func writeRegistry(path string, types []typeInfo) error {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by protocol/codec/internal/typegen; DO NOT EDIT.\n\n")
	buf.WriteString("package codec\n\n")
	buf.WriteString("import (\n")
	buf.WriteString("\tngapie \"github.com/free5gc/ngap/ie\"\n")
	buf.WriteString("\tngapmessage \"github.com/free5gc/ngap/message\"\n")
	buf.WriteString("\tnasie \"github.com/free5gc/nas/ie\"\n")
	buf.WriteString("\tnasmessage \"github.com/free5gc/nas/message\"\n")
	buf.WriteString(")\n\n")
	buf.WriteString("// upstreamTypes maps a stable CA-qualified Go type name to a constructor.\n")
	buf.WriteString("// It is generated from the pinned Free5GC modules and is only used by the\n")
	buf.WriteString("// canonical JSON projection; it is not a second protocol model.\n")
	buf.WriteString("var upstreamTypes = map[string]func() any{\n")
	for _, t := range types {
		pkg := map[string]string{
			"ngap.ie":      "ngapie",
			"ngap.message": "ngapmessage",
			"nas.ie":       "nasie",
			"nas.message":  "nasmessage",
		}[t.Package]
		fmt.Fprintf(&buf, "\t%q: func() any { return &%s.%s{} },\n", t.Qualified, pkg, t.Name)
	}
	buf.WriteString("}\n")
	return formatAndWrite(path, buf.Bytes())
}

type pendingMessage struct {
	structName string
	fileName   string
	fields     []nasField
}

func collectNASMessages(dir, ieDir string) ([]nasMessage, error) {
	files, err := parsePackage(dir)
	if err != nil {
		return nil, err
	}
	partialIEs, err := collectPartialIEs(ieDir)
	if err != nil {
		return nil, err
	}

	consts := map[string]uint64{}
	for _, file := range files {
		collectConsts(file, consts)
	}

	// Map message-type constant -> concrete struct from the ParseGSM switch.
	switchStructs, err := parseGSMSwitch(files)
	if err != nil {
		return nil, err
	}

	// Locate the struct declaration and its IEI constants.
	targets := map[string]bool{}
	for _, structName := range switchStructs {
		targets[structName] = true
	}
	summaries := map[string]pendingMessage{}
	for fileName, file := range files {
		ieis := map[string]uint8{}
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.CONST {
				continue
			}
			for _, spec := range gen.Specs {
				vs := spec.(*ast.ValueSpec)
				for i, name := range vs.Names {
					if i >= len(vs.Values) {
						continue
					}
					lit, ok := vs.Values[i].(*ast.BasicLit)
					if !ok || lit.Kind != token.INT {
						continue
					}
					if !strings.Contains(name.Name, "IEI") {
						continue
					}
					value, err := strconv.ParseUint(lit.Value, 0, 8)
					if err != nil {
						continue
					}
					ieis[name.Name] = uint8(value)
				}
			}
		}
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.TYPE {
				continue
			}
			for _, spec := range gen.Specs {
				ts := spec.(*ast.TypeSpec)
				st, ok := ts.Type.(*ast.StructType)
				if !ok || !targets[ts.Name.Name] {
					continue
				}
				fields, err := parseNASFields(st, ieis, partialIEs)
				if err != nil {
					return nil, fmt.Errorf("%s.%s: %w", fileName, ts.Name.Name, err)
				}
				summaries[ts.Name.Name] = pendingMessage{structName: ts.Name.Name, fileName: fileName, fields: fields}
			}
		}
	}

	out := []nasMessage{}
	for constName, structName := range switchStructs {
		code, ok := consts[constName]
		if !ok {
			return nil, fmt.Errorf("message-type constant %s has no value", constName)
		}
		pending, ok := summaries[structName]
		if !ok {
			return nil, fmt.Errorf("no struct layout found for %s", structName)
		}
		msg := nasMessage{
			Code:       uint8(code),
			StructName: structName,
			TypeName:   "nas.message." + structName,
		}
		for _, f := range pending.fields {
			if f.IEI == 0 {
				msg.Mandatory = append(msg.Mandatory, f)
			} else {
				msg.Optional = append(msg.Optional, f)
			}
		}
		out = append(out, msg)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Code < out[j].Code })
	return out, nil
}

func parseNASFields(st *ast.StructType, ieis map[string]uint8, partialIEs map[string]bool) ([]nasField, error) {
	fields := []nasField{}
	skipNext := false
	for _, field := range st.Fields.List {
		if len(field.Names) == 0 {
			continue
		}
		name := field.Names[0].Name
		if name == "PDUSessId" || name == "PTI" {
			continue
		}
		typeName := ""
		if star, ok := field.Type.(*ast.StarExpr); ok {
			switch inner := star.X.(type) {
			case *ast.Ident:
				typeName = inner.Name
			case *ast.SelectorExpr:
				typeName = inner.Sel.Name
			}
		} else if ident, ok := field.Type.(*ast.Ident); ok {
			typeName = ident.Name
		} else if sel, ok := field.Type.(*ast.SelectorExpr); ok {
			typeName = sel.Sel.Name
		}
		comment := ""
		if field.Comment != nil {
			comment = strings.TrimSpace(field.Comment.Text())
		}
		framing := ""
		size := 0
		if comment != "" {
			head := strings.SplitN(comment, ",", 2)[0]
			framing = strings.TrimSpace(head)
			if strings.Contains(comment, "B") {
				// A comment like "V, 2B" gives the value size. TV comments use
				// the total IE size (IEI plus value), which is not used here.
				parts := strings.Split(comment, ",")
				if len(parts) > 1 {
					sizePart := strings.TrimSpace(strings.TrimSuffix(parts[1], "B"))
					if n, err := strconv.Atoi(sizePart); err == nil {
						size = n
					}
				}
			}
		}
		f := nasField{Name: name, Type: typeName, Framing: framing, Size: size}
		if match, ok := matchIEI(name, ieis); ok {
			f.IEI = match
			f.Partial = partialIEs[typeName]
		}
		if f.IEI == 0 {
			// Mandatory field. The 0xC2 selected PST/SSC pair is encoded in one
			// half-octet each; skip the second field in the structural scan.
			if skipNext {
				skipNext = false
				continue
			}
			if strings.Contains(comment, "1/2B") {
				f.Size = 1
				skipNext = true
			}
			if f.Framing == "" {
				return nil, fmt.Errorf("mandatory field %s has no framing comment", name)
			}
		}
		fields = append(fields, f)
	}
	return fields, nil
}

func matchIEI(fieldName string, ieis map[string]uint8) (uint8, bool) {
	best := ""
	for name := range ieis {
		if strings.HasSuffix(name, fieldName) && len(name) > len(best) {
			best = name
		}
	}
	if best == "" {
		return 0, false
	}
	return ieis[best], true
}

func collectConsts(file *ast.File, out map[string]uint64) {
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.CONST {
			continue
		}
		for _, spec := range gen.Specs {
			vs := spec.(*ast.ValueSpec)
			for i, name := range vs.Names {
				if i >= len(vs.Values) {
					continue
				}
				lit, ok := vs.Values[i].(*ast.BasicLit)
				if !ok || lit.Kind != token.INT {
					continue
				}
				value, err := strconv.ParseUint(lit.Value, 0, 64)
				if err != nil {
					continue
				}
				out[name.Name] = value
			}
		}
	}
}

func parseGSMSwitch(files map[string]*ast.File) (map[string]string, error) {
	result := map[string]string{}
	for _, file := range files {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Name.Name != "ParseGSM" || fn.Body == nil {
				continue
			}
			ast.Inspect(fn.Body, func(node ast.Node) bool {
				sw, ok := node.(*ast.SwitchStmt)
				if !ok {
					return true
				}
				for _, stmt := range sw.Body.List {
					clause, ok := stmt.(*ast.CaseClause)
					if !ok || len(clause.Body) == 0 {
						continue
					}
					constName := caseConstName(clause.List)
					if constName == "" {
						continue
					}
					structName := assignedStruct(clause.Body)
					if structName != "" {
						result[constName] = structName
					}
				}
				return false
			})
		}
	}
	if len(result) == 0 {
		return nil, fmt.Errorf("ParseGSM switch not found")
	}
	return result, nil
}

func caseConstName(exprs []ast.Expr) string {
	for _, expr := range exprs {
		if ident, ok := expr.(*ast.Ident); ok {
			return ident.Name
		}
		call, ok := expr.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			continue
		}
		if ident, ok := call.Fun.(*ast.Ident); ok && ident.Name == "MsgType" {
			if arg, ok := call.Args[0].(*ast.Ident); ok {
				return arg.Name
			}
		}
	}
	return ""
}

func assignedStruct(body []ast.Stmt) string {
	for _, stmt := range body {
		assign, ok := stmt.(*ast.AssignStmt)
		if !ok || len(assign.Rhs) != 1 {
			continue
		}
		unary, ok := assign.Rhs[0].(*ast.UnaryExpr)
		if !ok || unary.Op != token.AND {
			continue
		}
		comp, ok := unary.X.(*ast.CompositeLit)
		if !ok {
			continue
		}
		if ident, ok := comp.Type.(*ast.Ident); ok {
			return ident.Name
		}
	}
	return ""
}

type n2Root struct {
	TypeName      string
	ContainerType string
	IEIDs         []int64
	Extensible    bool
}

func collectN2Roots(dir string) ([]n2Root, error) {
	files, err := parsePackage(dir)
	if err != nil {
		return nil, err
	}
	// Index struct fields and methods by type name.
	fieldsByType := map[string]*ast.StructType{}
	for _, file := range files {
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.TYPE {
				continue
			}
			for _, spec := range gen.Specs {
				ts := spec.(*ast.TypeSpec)
				st, ok := ts.Type.(*ast.StructType)
				if ok {
					fieldsByType[ts.Name.Name] = st
				}
			}
		}
	}

	roots := []n2Root{}
	for name, st := range fieldsByType {
		if !strings.HasSuffix(name, "Transfer") {
			continue
		}
		root := n2Root{TypeName: "ngap.ie." + name}
		for _, field := range st.Fields.List {
			if len(field.Names) != 1 || field.Names[0].Name != "ProtocolIEs" {
				continue
			}
			star, ok := field.Type.(*ast.StarExpr)
			if !ok {
				continue
			}
			ident, ok := star.X.(*ast.Ident)
			if !ok {
				continue
			}
			root.ContainerType = ident.Name
		}
		if root.ContainerType != "" {
			itemType, err := containerItemType(fieldsByType, root.ContainerType)
			if err != nil {
				return nil, fmt.Errorf("%s: %w", name, err)
			}
			ids, err := collectContainerIEIDs(files, itemType)
			if err != nil {
				return nil, fmt.Errorf("%s: %w", name, err)
			}
			root.IEIDs = ids
		}
		root.Extensible = isExtensibleRoot(files, name)
		roots = append(roots, root)
	}
	sort.Slice(roots, func(i, j int) bool { return roots[i].TypeName < roots[j].TypeName })
	return roots, nil
}

func containerItemType(fieldsByType map[string]*ast.StructType, containerType string) (string, error) {
	st, ok := fieldsByType[containerType]
	if !ok {
		return "", fmt.Errorf("container struct %s not found", containerType)
	}
	for _, field := range st.Fields.List {
		array, ok := field.Type.(*ast.ArrayType)
		if !ok {
			continue
		}
		if ident, ok := array.Elt.(*ast.Ident); ok {
			return ident.Name, nil
		}
	}
	return "", fmt.Errorf("container %s has no element type", containerType)
}

func collectContainerIEIDs(files map[string]*ast.File, typeName string) ([]int64, error) {
	constValues := map[string]int64{}
	for _, file := range files {
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.CONST {
				continue
			}
			for _, spec := range gen.Specs {
				vs := spec.(*ast.ValueSpec)
				for i, n := range vs.Names {
					if i >= len(vs.Values) {
						continue
					}
					lit, ok := vs.Values[i].(*ast.BasicLit)
					if !ok || lit.Kind != token.INT {
						continue
					}
					if v, err := strconv.ParseInt(lit.Value, 0, 64); err == nil {
						constValues[n.Name] = v
					}
				}
			}
		}
	}
	seen := map[int64]bool{}
	for _, file := range files {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || fn.Name.Name != "Read" || fn.Body == nil {
				continue
			}
			recv := receiverTypeName(fn)
			if recv != typeName {
				continue
			}
			ast.Inspect(fn.Body, func(node ast.Node) bool {
				bin, ok := node.(*ast.BinaryExpr)
				if !ok || bin.Op != token.EQL {
					return true
				}
				// Generated item decoders compare the reference field to a
				// literal: if id.Value == 130 { ... }.
				if lit, ok := bin.Y.(*ast.BasicLit); ok && lit.Kind == token.INT {
					if sel, ok := bin.X.(*ast.SelectorExpr); ok && sel.Sel.Name == "Value" {
						if v, err := strconv.ParseInt(lit.Value, 0, 64); err == nil && !seen[v] {
							seen[v] = true
						}
					}
					return true
				}
				sel, ok := bin.Y.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				pkg, ok := sel.X.(*ast.Ident)
				if !ok || pkg.Name != "ie" {
					return true
				}
				if !strings.HasPrefix(sel.Sel.Name, "ProtocolIEID") {
					return true
				}
				if v, ok := constValues[sel.Sel.Name]; ok && !seen[v] {
					seen[v] = true
				}
				return true
			})
		}
	}
	ids := make([]int64, 0, len(seen))
	for id := range seen {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	return ids, nil
}

func isExtensibleRoot(files map[string]*ast.File, typeName string) bool {
	for _, file := range files {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || fn.Name.Name != "Write" || fn.Body == nil {
				continue
			}
			if receiverTypeName(fn) != typeName {
				continue
			}
			extensible := false
			ast.Inspect(fn.Body, func(node ast.Node) bool {
				call, ok := node.(*ast.CallExpr)
				if !ok {
					return true
				}
				sel, ok := call.Fun.(*ast.SelectorExpr)
				if !ok || sel.Sel.Name != "WriteSequencePreambleBitMap" {
					return true
				}
				if len(call.Args) == 2 {
					if ident, ok := call.Args[1].(*ast.Ident); ok && ident.Name == "true" {
						extensible = true
					}
				}
				return true
			})
			return extensible
		}
	}
	return false
}

func receiverTypeName(fn *ast.FuncDecl) string {
	if fn.Recv == nil || len(fn.Recv.List) == 0 {
		return ""
	}
	expr := fn.Recv.List[0].Type
	for {
		star, ok := expr.(*ast.StarExpr)
		if ok {
			expr = star.X
			continue
		}
		if ident, ok := expr.(*ast.Ident); ok {
			return ident.Name
		}
		return ""
	}
}

func writeN2Meta(path string, roots []n2Root) error {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by protocol/codec/internal/typegen; DO NOT EDIT.\n\n")
	buf.WriteString("package codec\n\n")
	buf.WriteString("// n2Roots lists the Free5GC standalone N2 transfer roots. Roots with a\n")
	buf.WriteString("// ProtocolIE container also record the IE IDs the upstream container can\n")
	buf.WriteString("// decode; IDs outside the list are unsupported by that root.\n")
	buf.WriteString("var n2Roots = map[string]n2RootMeta{\n")
	for _, root := range roots {
		short := strings.TrimPrefix(root.TypeName, "ngap.ie.")
		fmt.Fprintf(&buf, "\t%q: {TypeName: %q, ContainerType: %q, Extensible: %t", short, root.TypeName, root.ContainerType, root.Extensible)
		if len(root.IEIDs) > 0 {
			buf.WriteString(", IEIDs: []int64{")
			for i, id := range root.IEIDs {
				if i > 0 {
					buf.WriteString(", ")
				}
				fmt.Fprintf(&buf, "%d", id)
			}
			buf.WriteString("}")
		}
		buf.WriteString("},\n")
	}
	buf.WriteString("}\n")
	return formatAndWrite(path, buf.Bytes())
}

func collectPartialIEs(dir string) (map[string]bool, error) {
	files, err := parsePackage(dir)
	if err != nil {
		return nil, err
	}
	partial := map[string]bool{}
	for _, file := range files {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || fn.Body == nil {
				continue
			}
			if fn.Name.Name != "UnmarshalBinary" && fn.Name.Name != "MarshalBinary" {
				continue
			}
			name := receiverTypeName(fn)
			if name == "" {
				continue
			}
			ast.Inspect(fn.Body, func(node ast.Node) bool {
				if ident, ok := node.(*ast.Ident); ok && ident.Name == "IEToDo" {
					partial[name] = true
				}
				return true
			})
		}
	}
	return partial, nil
}

type ngapMessage struct {
	Name          string
	TypeName      string
	ProcedureCode int64
	MessageType   int64
	Criticality   int64
}

func collectNGAPMessages(dir string) ([]ngapMessage, error) {
	files, err := parsePackage(dir)
	if err != nil {
		return nil, err
	}
	consts := map[string]int64{}
	for _, file := range files {
		for _, decl := range file.Decls {
			gen, ok := decl.(*ast.GenDecl)
			if !ok || gen.Tok != token.CONST {
				continue
			}
			for _, spec := range gen.Specs {
				vs := spec.(*ast.ValueSpec)
				for i, n := range vs.Names {
					if i >= len(vs.Values) {
						continue
					}
					lit, ok := vs.Values[i].(*ast.BasicLit)
					if !ok || lit.Kind != token.INT {
						continue
					}
					if v, err := strconv.ParseInt(lit.Value, 0, 64); err == nil {
						consts[n.Name] = v
					}
				}
			}
		}
	}
	byType := map[string]*ngapMessage{}
	for _, file := range files {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || fn.Body == nil {
				continue
			}
			name := receiverTypeName(fn)
			if name == "" {
				continue
			}
			var field *int64
			switch fn.Name.Name {
			case "ProcedureCode":
				if m, ok := byType[name]; ok {
					field = &m.ProcedureCode
				}
			case "MessageType":
				if m, ok := byType[name]; ok {
					field = &m.MessageType
				}
			case "Criticality":
				if m, ok := byType[name]; ok {
					field = &m.Criticality
				}
			default:
				continue
			}
			if field == nil {
				byType[name] = &ngapMessage{Name: name, TypeName: "ngap.message." + name}
				switch fn.Name.Name {
				case "ProcedureCode":
					field = &byType[name].ProcedureCode
				case "MessageType":
					field = &byType[name].MessageType
				case "Criticality":
					field = &byType[name].Criticality
				}
			}
			if value, ok := returnConstValue(fn.Body, consts); ok {
				*field = value
			}
		}
	}
	out := make([]ngapMessage, 0, len(byType))
	for _, msg := range byType {
		out = append(out, *msg)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].TypeName < out[j].TypeName })
	return out, nil
}

func returnConstValue(body *ast.BlockStmt, consts map[string]int64) (int64, bool) {
	for _, stmt := range body.List {
		ret, ok := stmt.(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			continue
		}
		switch expr := ret.Results[0].(type) {
		case *ast.Ident:
			if v, ok := consts[expr.Name]; ok {
				return v, true
			}
		case *ast.BasicLit:
			if expr.Kind == token.INT {
				if v, err := strconv.ParseInt(expr.Value, 0, 64); err == nil {
					return v, true
				}
			}
		case *ast.CallExpr:
			// Criticality() returns aper.Enumerated; generated code may use a
			// bare constant today, so nothing further is needed.
		}
	}
	return 0, false
}

func writeNGAPMeta(path string, messages []ngapMessage) error {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by protocol/codec/internal/typegen; DO NOT EDIT.\n\n")
	buf.WriteString("package codec\n\n")
	buf.WriteString("// ngapMessages lists every generated NGAP PDU message type and its fixed\n")
	buf.WriteString("// procedure/message-type metadata. It is capability data, not a codec.\n")
	buf.WriteString("var ngapMessages = []ngapMessageMeta{\n")
	for _, msg := range messages {
		fmt.Fprintf(&buf, "\t{Name: %q, TypeName: %q, ProcedureCode: %d, MessageType: %d, Criticality: %d},\n",
			msg.Name, msg.TypeName, msg.ProcedureCode, msg.MessageType, msg.Criticality)
	}
	buf.WriteString("}\n")
	return formatAndWrite(path, buf.Bytes())
}

func writeNASMeta(path string, messages []nasMessage) error {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by protocol/codec/internal/typegen; DO NOT EDIT.\n\n")
	buf.WriteString("package codec\n\n")
	buf.WriteString("// nasMessages lists the upstream ParseGSM dispatch and the structural IEI\n")
	buf.WriteString("// layout used only for duplicate/unknown IE detection. The layout is derived\n")
	buf.WriteString("// from the pinned module's own declarations, not a second decoder.\n")
	buf.WriteString("var nasMessages = map[uint8]nasMessageMeta{\n")
	for _, msg := range messages {
		fmt.Fprintf(&buf, "\t0x%02x: {\n", msg.Code)
		fmt.Fprintf(&buf, "\t\tStructName: %q,\n", msg.StructName)
		fmt.Fprintf(&buf, "\t\tTypeName: %q,\n", msg.TypeName)
		if len(msg.Mandatory) > 0 {
			buf.WriteString("\t\tMandatory: []nasIEMeta{\n")
			for _, f := range msg.Mandatory {
				fmt.Fprintf(&buf, "\t\t\t{Field: %q, Framing: %q, Size: %d},\n", f.Name, f.Framing, f.Size)
			}
			buf.WriteString("\t\t},\n")
		}
		if len(msg.Optional) > 0 {
			buf.WriteString("\t\tOptional: []nasIEMeta{\n")
			for _, f := range msg.Optional {
				fmt.Fprintf(&buf, "\t\t\t{IEI: 0x%02x, Field: %q, Type: %q, Framing: %q, Size: %d, Partial: %t},\n", f.IEI, f.Name, f.Type, f.Framing, f.Size, f.Partial)
			}
			buf.WriteString("\t\t},\n")
		}
		buf.WriteString("\t},\n")
	}
	buf.WriteString("}\n")
	return formatAndWrite(path, buf.Bytes())
}

func formatAndWrite(path string, src []byte) error {
	formatted, err := format.Source(src)
	if err != nil {
		return fmt.Errorf("format %s: %w", path, err)
	}
	return os.WriteFile(path, formatted, 0o644)
}
